mod tests {
    use super::*;
    use std::io::{Error, ErrorKind};

    #[test]
    fn internal_server_error() {
        let response = InternalServerError(Error::new(ErrorKind::Other, "Test")).into_response();
        assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
    }
}

